// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceDeviceStore {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceDeviceStore = UniffiVTableCallbackInterfaceDeviceStore(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeDeviceStore.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface DeviceStore: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeDeviceStore.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface DeviceStore: handle missing in uniffiClone")
            }
        },
        get: { (
            uniffiHandle: UInt64,
            scopeKey: RustBuffer,
            key: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> String? in
                guard let uniffiObj = try? FfiConverterTypeDeviceStore.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.get(
                     scopeKey: try FfiConverterString.lift(scopeKey),
                     key: try FfiConverterTypeStoreKey_lift(key)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterOptionString.lower($0) }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypeClientError_lower
            )
        },
        set: { (
            uniffiHandle: UInt64,
            scopeKey: RustBuffer,
            key: RustBuffer,
            value: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
