public enum StoreKey: Equatable, Hashable {
    
    case configuration
    case deviceToken(account: String
    )
    case profile(account: String, version: String, tokenHash: String
    )
    case workspace(account: String, version: String
    )
    case inboxCache(account: String, version: String, tokenHash: String
    )
    case inboxJournal(account: String, tokenHash: String
    )
    /**
     * Protected registration state, not a disposable cache. At most 24 KiB.
     */
    case pushState





}

#if compiler(>=6)
extension StoreKey: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeStoreKey: FfiConverterRustBuffer {
    typealias SwiftType = StoreKey

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> StoreKey {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .configuration
        
        case 2: return .deviceToken(account: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .profile(account: try FfiConverterString.read(from: &buf), version: try FfiConverterString.read(from: &buf), tokenHash: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .workspace(account: try FfiConverterString.read(from: &buf), version: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .inboxCache(account: try FfiConverterString.read(from: &buf), version: try FfiConverterString.read(from: &buf), tokenHash: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .inboxJournal(account: try FfiConverterString.read(from: &buf), tokenHash: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .pushState
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: StoreKey, into buf: inout [UInt8]) {
        switch value {
        
        
        case .configuration:
            writeInt(&buf, Int32(1))
        
        
        case let .deviceToken(account):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(account, into: &buf)
            
        
        case let .profile(account,version,tokenHash):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(account, into: &buf)
            FfiConverterString.write(version, into: &buf)
            FfiConverterString.write(tokenHash, into: &buf)
            
        
        case let .workspace(account,version):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(account, into: &buf)
            FfiConverterString.write(version, into: &buf)
            
        
        case let .inboxCache(account,version,tokenHash):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(account, into: &buf)
            FfiConverterString.write(version, into: &buf)
            FfiConverterString.write(tokenHash, into: &buf)
            
        
        case let .inboxJournal(account,tokenHash):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(account, into: &buf)
            FfiConverterString.write(tokenHash, into: &buf)
            
        
        case .pushState:
            writeInt(&buf, Int32(7))
        
        }
    }
}


